script:
(function () {
  'use strict';
  // Roth / pre-tax split that keeps this year's taxable income at the top of a chosen bracket.
  //   Taxable income with all-Roth deferrals TI = wages - other pre-tax deductions - deduction
  //     (the 2026 standard deduction when 0 is entered).
  //   Pre-tax part = min(deferral - forced Roth, max(0, TI - top of the chosen bracket)); the rest is Roth.
  //     Forced Roth: age-50 catch-up dollars when wages are above the Roth catch-up threshold.
  //   Tax saved = tax(TI) - tax(TI - pre-tax part) on the 2026 brackets + state rate x pre-tax part.
  //   Projection: the same split each year at the start of the year, growing at r; tax saved is
  //     invested in a taxable account at r x (1 - tax rate on returns). After tax = Roth + pre-tax x
  //     (1 - retirement rate) + invested savings.
  // Checked in Node (fake DOM, whole script, tests/rsp.test.js): single, $125,000 wages, standard
  //   deduction -> TI $108,900; 22% bracket top $105,700 -> $3,200 pre-tax, $21,300 Roth, tax saved
  //   $768 (24%); $819.23 Roth / $123.08 pre-tax per biweekly paycheck; MFJ $250,000, 12% target -> all
  //   $24,500 pre-tax, saving $5,518 ($6,400 at 24% + $18,100 at 22%); age 55, $200,000 wages, $32,500 ->
  //   at most $24,500 pre-tax ($8,000 forced Roth); $24,500 at 6% for 25 years, start of year = $1,424,831.
  //
  // ---- 2026 FEDERAL TAX FIGURES AND LIMITS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21), same table as
  // take-home-paycheck-calculator. Upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%.
  var TAX_YEAR = 2026;
  var BRACKETS = {
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  // IRS Notice 2025-67: deferral limit $24,500; catch-up $8,000 at 50+, $11,250 at 60-63; catch-ups
  // must be Roth if prior-year (2025) FICA wages from the employer exceeded $150,000 (IRC 414(v)(7)).
  var LIMITS = { deferral: 24500, catchUp50: 8000, catchUp60to63: 11250, rothCatchUpWages: 150000 };
  // ------------------------------------------------------------------------------------------------

  function tax(income, status) {
    var b = BRACKETS[status], t = 0, lower = 0;
    for (var k = 0; k < RATES.length; k++) {
      var upper = k < b.length ? b[k] : Infinity;
      if (income > lower) t += (Math.min(income, upper) - lower) * RATES[k];
      lower = upper;
    }
    return t;
  }
  function topRate(income, status) {
    var b = BRACKETS[status];
    for (var k = 0; k < b.length; k++) if (income <= b[k]) return RATES[k];
    return RATES[RATES.length - 1];
  }
  function limitFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.deferral + LIMITS.catchUp60to63;
    return LIMITS.deferral + (age >= 50 ? LIMITS.catchUp50 : 0);
  }

  function scenario(p, pre) {
    var roth = p.deferral - pre;
    var fedSaved = tax(p.ti, p.status) - tax(p.ti - pre, p.status), saved = fedSaved + pre * p.stateRate;
    var rb = 0, pb = 0, side = 0, sideRate = p.rate * (1 - p.investTax);
    for (var y = 0; y < p.years; y++) {
      rb = (rb + roth) * (1 + p.rate); pb = (pb + pre) * (1 + p.rate); side = (side + saved) * (1 + sideRate);
    }
    return { roth: roth, pre: pre, saved: saved, cost: p.deferral - saved, ti: p.ti - pre, top: topRate(p.ti - pre, p.status),
             rothBal: rb, preBal: pb, side: side, after: rb + pb * (1 - p.taxLater) + side,
             share: rb + pb > 0 ? rb / (rb + pb) : 0 };
  }
  // p: status, ti, deferral, forced, target (index), stateRate, years, rate, taxLater, investTax
  function plan(p) {
    var maxPre = p.deferral - p.forced, top = BRACKETS[p.status][p.target];
    var pre = Math.min(maxPre, Math.max(0, p.ti - top));
    return { top: top, allRoth: scenario(p, 0), split: scenario(p, pre), allPre: scenario(p, maxPre) };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var status = document.getElementById('rspStatus').value, wages = num('rspWages'), deferral = num('rspDeferral'),
        age = num('rspAge'), target = parseInt(document.getElementById('rspTarget').value, 10),
        freq = parseInt(document.getElementById('rspFreq').value, 10), stateRate = num('rspState'),
        retireAge = num('rspRetireAge'), rate = num('rspRate'), taxLater = num('rspTaxLater'), other = num('rspOther'),
        deduction = num('rspDeduction'), investTax = num('rspInvestTax');
    var error = document.getElementById('rspError');
    var limit = isNaN(age) ? 0 : limitFor(age);
    var bad = [wages, deferral, age, stateRate, retireAge, rate, taxLater, other, deduction, investTax].some(isNaN) ||
              wages <= 0 || deferral <= 0 || deferral > limit || other < 0 || deferral + other > wages || deduction < 0 ||
              age !== Math.round(age) || retireAge !== Math.round(retireAge) || age < 16 || age > 99 || retireAge <= age ||
              retireAge > 100 || stateRate < 0 || stateRate > 20 || rate < -20 || rate > 30 || taxLater < 0 || taxLater > 70 ||
              investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter wages above $0 and a deferral above $0 up to your 2026 limit (' + fmt(limit || LIMITS.deferral) +
                          ') that fits in your wages, whole-number ages from 16 to 99 with retirement later (up to 100), ' +
                          'a state rate up to 20%, a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var ti = Math.max(0, wages - other - (deduction > 0 ? deduction : STANDARD_DEDUCTION[status]));
    var forced = age >= 50 && wages > LIMITS.rothCatchUpWages ? Math.max(0, deferral - LIMITS.deferral) : 0;
    var r = plan({ status: status, ti: ti, deferral: deferral, forced: forced, target: target, stateRate: stateRate / 100,
                   years: retireAge - age, rate: rate / 100, taxLater: taxLater / 100, investTax: investTax / 100 });
    var s = r.split;
    set('rspRothPay', cents.format(s.roth / freq));
    set('rspPrePay', cents.format(s.pre / freq));
    set('rspRothPct', pct(s.roth / wages) + ' of pay');
    set('rspPrePct', pct(s.pre / wages) + ' of pay');
    set('rspSplitNote', fmt(s.roth) + ' Roth and ' + fmt(s.pre) + ' pre-tax a year, ' + freq + ' paychecks.');
    set('rspTiRoth', fmt(ti) + ' (' + pct(topRate(ti, status)) + ' bracket)');
    set('rspTop', fmt(r.top) + ' (' + pct(RATES[target]) + ')');
    set('rspTiSplit', fmt(s.ti));
    set('rspSaved', fmt(s.saved));
    set('rspLimit', fmt(limit));
    var cn = document.getElementById('rspCatchNote');
    cn.hidden = !(forced > 0);
    set('rspCatchNote', 'Your wages are above ' + fmt(LIMITS.rothCatchUpWages) + ', so your ' + fmt(forced) + ' of catch-up deferrals ' +
        'must be Roth in 2026 (the test uses your 2025 wages from this employer; this assumes they were similar).');
    set('rspCompareIntro', 'The same deferral every year until age ' + retireAge + ', using 2026 brackets and limits throughout.');
    var lines = [
      ['Roth deferral a year', 'roth', fmt], ['Pre-tax deferral a year', 'pre', fmt],
      ['Income tax saved in 2026', 'saved', fmt], ['Take-home pay cost', 'cost', fmt],
      ['Taxable income', 'ti', fmt], ['Top federal rate', 'top', pct],
      ['Roth balance at retirement', 'rothBal', fmt], ['Pre-tax balance at retirement', 'preBal', fmt],
      ['Invested tax savings', 'side', fmt], ['Total after tax', 'after', fmt], ['Roth share of plan savings', 'share', pct]
    ];
    var body = document.getElementById('rspCompare');
    body.textContent = '';
    lines.forEach(function (l) {
      var tr = document.createElement('tr');
      var th = document.createElement('th'); th.setAttribute('scope', 'row'); th.textContent = l[0]; tr.appendChild(th);
      [r.allRoth, r.split, r.allPre].forEach(function (x) {
        var td = document.createElement('td'); td.textContent = l[2](x[l[1]]); tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rspForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
